function getEnglishCategory(cat) {
  const map = {
    hidden: 'Hidden & Subtle Blessings',
    body: 'Health & Bodily Blessings',
    spiritual: 'Spiritual & Faith Blessings',
    family: 'Family & Kinship Blessings',
    daily: 'Daily Life Blessings'
  };
  return map[cat] || 'Divine Blessings';
}

function getEnglishSource(src) {
  if (!src) return '';
  return src
    .replace('سورة ', 'Surah ')
    .replace('صحيح البخاري ومسلم', 'Sahih al-Bukhari & Muslim')
    .replace('صحيح البخاري', 'Sahih al-Bukhari')
    .replace('صحيح مسلم', 'Sahih Muslim')
    .replace('سنن أبي داود والترمذي', 'Sunan Abi Dawood & At-Tirmidhi')
    .replace('سنن أبي داود', 'Sunan Abi Dawood')
    .replace('سنن الترمذي وابن ماجه', 'Jami` at-Tirmidhi & Ibn Majah')
    .replace('سنن الترمذي', 'Jami` at-Tirmidhi')
    .replace('سنن النسائي', 'Sunan an-Nasa\'i')
    .replace('مسند الإمام أحمد', 'Musnad Ahmad')
    .replace('رواه الطبراني والبيهقي', 'At-Tabarani & Al-Bayhaqi');
}

function getDetailedEnglishReflection(b) {
  // Return thoughtful contemplation in English tailored to category and theme
  const intro = {
    hidden: "A subtle, hidden grace from Allah that surrounds you constantly without noise: Were it not for His silent protection and gentle mercy, life would be burdened with distress. Contemplate this concealed favor and turn your heart in humble gratitude to your Sustainer.",
    body: "An intricate physiological and bodily wonder operating within you every single second: Thousands of microscopic mechanisms work in flawless harmony without your conscious effort or pain. How immense is Allah's perfection in fashioning the human being.",
    spiritual: "A profound spiritual treasure bestowed by Allah upon the believer's heart: It connects the soul to its Creator, infuses daily life with serene purpose, and opens doors to eternal peace in this world and the Hereafter.",
    family: "A cherished blessing of human connection, affection, and mutual mercy: Allah placed love in the hearts of family, friends, and righteous companions to soften the hardships of life and share the joy of companionship.",
    daily: "A simple, everyday convenience that we so often take for granted because of its familiarity: It enriches our daily routine and protects our comfort. Remember to thank the Bestower for every humble, daily provision."
  };

  return intro[b.category] || "Reflect on this divine favor with a present heart, recognizing that all grace belongs solely to Allah, the Most Merciful.";
}

